-- For window rules and layerrules
-- See https://wiki.hyprland.org/Configuring/Window-Rules/ for more

-- This file is used to add or overwrite window rules
-- This file will not be modified during dotfiles updates

-- Border colors for fullscreen states
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    match = {
        fullscreen = 1,
    },
    border_color = "rgb(FB4934) rgb(FB4934)",
})

-- Zen browser - transparent with blur
hl.window_rule({
    match = {
        class = "^(zen-alpha|zen)$",
    },
    opacity = 0.99,
    no_blur = true,
})

-- Gromit annotation overlay
hl.window_rule({
    match = {
        class = "^([Gg]romit-mpx)$",
    },
    float = true,
    no_blur = true,
    no_anim = true,
    opacity = "1 override 1 override",
    no_shadow = true,
    fullscreen_state = "0 2",
    size = "100% 100%",
})
